import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { expect, test } from '@playwright/test'

import { uploadFixture } from '../helpers/fileUpload'

const currentDir = path.dirname(fileURLToPath(import.meta.url))
// Generated by tools/make-sxf-sample.py; also served as demo samples.
const samples = path.resolve(currentDir, '../../../../resources/cad-data/samples')

for (const ext of ['sfc', 'p21', 'sfz', 'p2z']) {
  test(`opens an SXF .${ext} drawing`, async ({ page }) => {
    const pageErrors: string[] = []
    page.on('pageerror', error => pageErrors.push(error.message))

    await page.goto('/')
    const fileInput = page.locator('input[type="file"]').first()
    await expect(fileInput).toHaveAttribute('accept', new RegExp(`\\.${ext}`))
    await uploadFixture(page, path.join(samples, `sxf-sample.${ext}`))

    await expect(page.locator('.ml-cad-container canvas').first()).toBeVisible()
    await expect(page.getByText(`sxf-sample.${ext}`).first()).toBeVisible()
    await expect(page.getByText(/Failed to open/)).toHaveCount(0)
    expect(pageErrors).toEqual([])
  })
}
